114: func (r *Reader) iterateInternal(ctx context.Context, afterBatchID string, beforeTime *time.Time) iter.Seq2[*OpBatch, error] {
115: 	return func(yield func(*OpBatch, error) bool) {
116: 		if ctx == nil {
117: 			ctx = context.Background()
118: 		}
119: 
120: 		if err := ctx.Err(); err != nil {
121: 			yield(nil, err)
122: 			return
123: 		}
124: 
125: 		entries, err := os.ReadDir(r.baseDir)
126: 		if errors.Is(err, os.ErrNotExist) {
127: 			return
128: 		}
129: 		if err != nil {
130: 			yield(nil, fmt.Errorf("read ops base dir %s: %w", r.baseDir, err))
131: 			return
132: 		}
133: 
134: 		var monthDirs []string
135: 		for _, entry := range entries {
136: 			if !entry.IsDir() {
137: 				continue
138: 			}
139: 			name := entry.Name()
140: 			if _, parseErr := time.Parse("2006-01", name); parseErr == nil {
141: 				monthDirs = append(monthDirs, name)
142: 			}
143: 		}
144: 		sort.Strings(monthDirs)
145: 
146: 		seenAfter := (afterBatchID == "")
147: 
148: 		for _, monthDir := range monthDirs {
149: 			if err := ctx.Err(); err != nil {
150: 				yield(nil, err)
151: 				return
152: 			}
153: 
154: 			monthPath := filepath.Join(r.baseDir, monthDir)
155: 			fileEntries, err := os.ReadDir(monthPath)
156: 			if err != nil {
157: 				if !yield(nil, fmt.Errorf("read month dir %s: %w", monthPath, err)) {
158: 					return
159: 				}
160: 				continue
161: 			}
162: 
163: 			var jsonFiles []os.DirEntry
164: 			for _, f := range fileEntries {
165: 				if !f.IsDir() && strings.HasSuffix(f.Name(), ".json") {
166: 					jsonFiles = append(jsonFiles, f)
167: 				}
168: 			}
169: 
170: 			sort.Slice(jsonFiles, func(i, j int) bool {
171: 				return jsonFiles[i].Name() < jsonFiles[j].Name()
172: 			})
173: 
174: 			for _, f := range jsonFiles {
175: 				if err := ctx.Err(); err != nil {
176: 					yield(nil, err)
177: 					return
178: 				}
179: 
180: 				filePath := filepath.Join(monthPath, f.Name())
181: 				batch, err := r.ReadBatch(filePath)
182: 				if err != nil {
183: 					if !yield(nil, fmt.Errorf("read batch %s: %w", filePath, err)) {
184: 						return
185: 					}
186: 					continue
187: 				}
188: 
189: 				if !seenAfter {
190: 					if batch.BatchID == afterBatchID {
191: 						seenAfter = true
192: 						continue
193: 					}
194: 					if strings.ToUpper(batch.BatchID) > strings.ToUpper(afterBatchID) {
195: 						seenAfter = true
196: 					} else {
197: 						continue
198: 					}
199: 				}
200: 
201: 				if beforeTime != nil && !batch.CreatedAt.UTC().Before(beforeTime.UTC()) {
202: 					continue
203: 				}
204: 
205: 				if !yield(batch, nil) {
206: 					return
207: 				}
208: 			}
209: 		}
210: 	}
211: }
