package dossiers

import (
	"strings"
	"time"
)

// EntryType represents the type of a dossier entry.
type EntryType string

const (
	TypeInvariant        EntryType = "invariant"
	TypeRuledOut         EntryType = "ruled-out"
	TypeFailureSignature EntryType = "failure-signature"
	TypeGotcha           EntryType = "gotcha"
	TypeDecision         EntryType = "decision"
	TypeProcedure        EntryType = "procedure"
	TypeInterface        EntryType = "interface"
	TypeOpenIssue        EntryType = "open-issue"
)

// TypePrefixes maps each EntryType to its canonical ID prefix.
var TypePrefixes = map[EntryType]string{
	TypeInvariant:        "inv-",
	TypeRuledOut:         "rul-",
	TypeFailureSignature: "fail-",
	TypeGotcha:           "got-",
	TypeDecision:         "dec-",
	TypeProcedure:        "proc-",
	TypeInterface:        "iface-",
	TypeOpenIssue:        "issue-",
}

// PrefixToType maps ID prefixes to EntryType.
var PrefixToType = map[string]EntryType{
	"inv-":   TypeInvariant,
	"rul-":   TypeRuledOut,
	"fail-":  TypeFailureSignature,
	"got-":   TypeGotcha,
	"dec-":   TypeDecision,
	"proc-":  TypeProcedure,
	"iface-": TypeInterface,
	"issue-": TypeOpenIssue,
}

// TypeFromID infers the EntryType from an entry ID based on known prefixes.
// Returns an empty EntryType if prefix is not recognized.
func TypeFromID(id string) EntryType {
	for prefix, entryType := range PrefixToType {
		if strings.HasPrefix(id, prefix) {
			return entryType
		}
	}
	return ""
}

// PrefixForType returns the ID prefix for the given EntryType.
func PrefixForType(t EntryType) string {
	if p, ok := TypePrefixes[t]; ok {
		return p
	}
	return ""
}

// Entry represents an entry within a dossier.
type Entry struct {
	ID            string    `json:"id"`
	Type          EntryType `json:"type"`
	DossierScope  string    `json:"dossier_scope"`
	Text          string    `json:"text"`
	Anchors       []string  `json:"anchors,omitempty"`
	Evidence      []string  `json:"evidence,omitempty"`
	Verified      string    `json:"verified,omitempty"`
	ClosesWhen    string    `json:"closes_when,omitempty"`
	Source        string    `json:"source,omitempty"`
	CreatedAt     time.Time `json:"created_at"`
	UpdatedAt     time.Time `json:"updated_at"`
	Retired       bool      `json:"retired,omitempty"`
	RetiredReason string    `json:"retired_reason,omitempty"`
	SupersededBy  string    `json:"superseded_by,omitempty"`
}

package dossiers

import (
	"sort"
	"strings"
	"time"
)

// DossierKind represents the kind of a dossier.
type DossierKind string

const (
	KindModule    DossierKind = "module"
	KindTopic     DossierKind = "topic"
	KindExternal  DossierKind = "external"
	KindProcedure DossierKind = "procedure"
)

// InferKind infers a DossierKind from the dossier scope string.
func InferKind(scope string) DossierKind {
	scope = strings.TrimSpace(scope)
	if strings.HasPrefix(scope, "external/") || scope == "external" {
		return KindExternal
	}
	if strings.HasPrefix(scope, "procedure/") || strings.HasPrefix(scope, "procedures/") || scope == "procedure" || scope == "procedures" {
		return KindProcedure
	}
	if strings.HasPrefix(scope, "topic/") || strings.HasPrefix(scope, "topics/") || scope == "topic" || scope == "topics" {
		return KindTopic
	}
	return KindModule
}

// Dossier represents a rendered or projectable dossier page.
type Dossier struct {
	Scope   string      `json:"scope"`
	Kind    DossierKind `json:"kind"`
	Title   string      `json:"title"`
	Purpose string      `json:"purpose"`
	Entries []Entry     `json:"entries"`
	History []Entry     `json:"history"`
}

// Atlas represents the catalog of all dossiers in the repository.
type Atlas struct {
	Dossiers []AtlasEntry `json:"dossiers"`
}

// AtlasEntry represents a single dossier's summary in the Atlas.
type AtlasEntry struct {
	Scope       string      `json:"scope"`
	Kind        DossierKind `json:"kind"`
	Title       string      `json:"title"`
	EntryCount  int         `json:"entry_count"`
	LastUpdated time.Time   `json:"last_updated"`
}

// BuildAtlas constructs an Atlas from a map of dossiers, sorted by scope.
func BuildAtlas(dossiers map[string]*Dossier) *Atlas {
	entries := make([]AtlasEntry, 0, len(dossiers))
	for _, d := range dossiers {
		var lastUpdated time.Time
		for _, e := range d.Entries {
			if e.UpdatedAt.After(lastUpdated) {
				lastUpdated = e.UpdatedAt
			}
		}
		for _, e := range d.History {
			if e.UpdatedAt.After(lastUpdated) {
				lastUpdated = e.UpdatedAt
			}
		}

		entries = append(entries, AtlasEntry{
			Scope:       d.Scope,
			Kind:        d.Kind,
			Title:       d.Title,
			EntryCount:  len(d.Entries),
			LastUpdated: lastUpdated,
		})
	}

	sort.Slice(entries, func(i, j int) bool {
		return entries[i].Scope < entries[j].Scope
	})

	return &Atlas{
		Dossiers: entries,
	}
}

package dossiers

import (
	"context"
	"errors"
	"fmt"
	"iter"
	"sort"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/ops"
)

// Projector projects an append-only ops log into structured Dossiers.
type Projector struct {
	opsReader *ops.Reader
}

// NewProjector creates a new Projector using the provided ops.Reader.
func NewProjector(opsReader *ops.Reader) *Projector {
	return &Projector{
		opsReader: opsReader,
	}
}

// Project iterates all ops from the op log and builds the latest dossier state.
func (p *Projector) Project(ctx context.Context) (map[string]*Dossier, error) {
	if p.opsReader == nil {
		return nil, errors.New("ops reader is nil")
	}
	return p.projectSeq(p.opsReader.Iterate(ctx))
}

// ProjectBefore projects ops committed before the given git commit.
func (p *Projector) ProjectBefore(ctx context.Context, beforeCommit string) (map[string]*Dossier, error) {
	if p.opsReader == nil {
		return nil, errors.New("ops reader is nil")
	}
	return p.projectSeq(p.opsReader.IterateBefore(ctx, beforeCommit))
}

func (p *Projector) projectSeq(seq iter.Seq2[*ops.OpBatch, error]) (map[string]*Dossier, error) {
	dossiers := make(map[string]*Dossier)

	getOrCreateDossier := func(scope string) *Dossier {
		d, ok := dossiers[scope]
		if !ok {
			d = &Dossier{
				Scope: scope,
				Kind:  InferKind(scope),
				Title: scope,
			}
			dossiers[scope] = d
		}
		return d
	}

	findActiveEntry := func(scopeHint, entryID string) (*Dossier, int, *Entry) {
		if scopeHint != "" {
			if d, ok := dossiers[scopeHint]; ok {
				for i := range d.Entries {
					if d.Entries[i].ID == entryID {
						return d, i, &d.Entries[i]
					}
				}
			}
		}
		for _, d := range dossiers {
			for i := range d.Entries {
				if d.Entries[i].ID == entryID {
					return d, i, &d.Entries[i]
				}
			}
		}
		return nil, -1, nil
	}

	for batch, err := range seq {
		if err != nil {
			return nil, fmt.Errorf("iterate ops batch: %w", err)
		}
		if batch == nil {
			continue
		}

		for _, op := range batch.Ops {
			ts := op.Timestamp
			if ts.IsZero() {
				ts = batch.CreatedAt
			}

			switch op.Type {
			case ops.OpAdd:
				d := getOrCreateDossier(op.DossierScope)

				if purpose := getString(op.Fields, "purpose"); purpose != "" {
					d.Purpose = purpose
				} else if dPurpose := getString(op.Fields, "dossier_purpose"); dPurpose != "" {
					d.Purpose = dPurpose
				}

				if title := getString(op.Fields, "title"); title != "" {
					d.Title = title
				} else if dTitle := getString(op.Fields, "dossier_title"); dTitle != "" {
					d.Title = dTitle
				}

				if kind := getString(op.Fields, "kind"); kind != "" {
					d.Kind = DossierKind(kind)
				} else if dKind := getString(op.Fields, "dossier_kind"); dKind != "" {
					d.Kind = DossierKind(dKind)
				}

				entryType := EntryType(getString(op.Fields, "type"))
				if entryType == "" {
					entryType = TypeFromID(op.EntryID)
				}
				if entryType == "" {
					entryType = TypeInvariant
				}

				entry := Entry{
					ID:           op.EntryID,
					Type:         entryType,
					DossierScope: op.DossierScope,
					Text:         getString(op.Fields, "text"),
					Anchors:      getStringSlice(op.Fields, "anchors"),
					Evidence:     getStringSlice(op.Fields, "evidence"),
					Verified:     getString(op.Fields, "verified"),
					ClosesWhen:   getString(op.Fields, "closes_when"),
					Source:       op.Source,
					CreatedAt:    ts,
					UpdatedAt:    ts,
				}

				// If entry already exists, update in-place; otherwise append
				_, idx, _ := findActiveEntry(op.DossierScope, op.EntryID)
				if idx >= 0 {
					d.Entries[idx] = entry
				} else {
					d.Entries = append(d.Entries, entry)
				}

			case ops.OpAmend:
				d, idx, existing := findActiveEntry(op.DossierScope, op.EntryID)
				if existing != nil {
					if text := getString(op.Fields, "text"); text != "" {
						existing.Text = text
					}
					if tStr := getString(op.Fields, "type"); tStr != "" {
						existing.Type = EntryType(tStr)
					}
					if anchors := getStringSlice(op.Fields, "anchors"); anchors != nil {
						existing.Anchors = anchors
					}
					if evidence := getStringSlice(op.Fields, "evidence"); evidence != nil {
						existing.Evidence = evidence
					}
					if verified := getString(op.Fields, "verified"); verified != "" {
						existing.Verified = verified
					}
					if closesWhen := getString(op.Fields, "closes_when"); closesWhen != "" {
						existing.ClosesWhen = closesWhen
					}
					if op.Source != "" {
						existing.Source = op.Source
					}
					existing.UpdatedAt = ts
					d.Entries[idx] = *existing
				}

				// Allow amending dossier-level properties
				targetD := d
				if targetD == nil && op.DossierScope != "" {
					targetD = getOrCreateDossier(op.DossierScope)
				}
				if targetD != nil {
					if purpose := getString(op.Fields, "purpose"); purpose != "" {
						targetD.Purpose = purpose
					} else if dPurpose := getString(op.Fields, "dossier_purpose"); dPurpose != "" {
						targetD.Purpose = dPurpose
					}
					if title := getString(op.Fields, "title"); title != "" {
						targetD.Title = title
					} else if dTitle := getString(op.Fields, "dossier_title"); dTitle != "" {
						targetD.Title = dTitle
					}
					if kind := getString(op.Fields, "kind"); kind != "" {
						targetD.Kind = DossierKind(kind)
					} else if dKind := getString(op.Fields, "dossier_kind"); dKind != "" {
						targetD.Kind = DossierKind(dKind)
					}
				}

			case ops.OpSupersede:
				newEntryID := getString(op.Fields, "new_entry_id")
				reason := getString(op.Fields, "reason")
				if reason == "" {
					reason = "superseded by " + newEntryID
				}

				var oldScope string
				var oldType EntryType
				var oldAnchors, oldEvidence []string
				var oldVerified, oldClosesWhen string

				d, idx, oldEntry := findActiveEntry(op.DossierScope, op.EntryID)
				if oldEntry != nil {
					oldScope = oldEntry.DossierScope
					oldType = oldEntry.Type
					oldAnchors = oldEntry.Anchors
					oldEvidence = oldEntry.Evidence
					oldVerified = oldEntry.Verified
					oldClosesWhen = oldEntry.ClosesWhen

					retiredEntry := *oldEntry
					retiredEntry.Retired = true
					retiredEntry.RetiredReason = reason
					retiredEntry.SupersededBy = newEntryID
					retiredEntry.UpdatedAt = ts

					d.Entries = append(d.Entries[:idx], d.Entries[idx+1:]...)
					d.History = append(d.History, retiredEntry)
				}

				targetScope := op.DossierScope
				if targetScope == "" {
					targetScope = oldScope
				}
				targetD := getOrCreateDossier(targetScope)

				newType := EntryType(getString(op.Fields, "type"))
				if newType == "" {
					newType = TypeFromID(newEntryID)
				}
				if newType == "" {
					newType = oldType
				}
				if newType == "" {
					newType = TypeInvariant
				}

				anchors := getStringSlice(op.Fields, "anchors")
				if anchors == nil {
					anchors = oldAnchors
				}
				evidence := getStringSlice(op.Fields, "evidence")
				if evidence == nil {
					evidence = oldEvidence
				}
				verified := getString(op.Fields, "verified")
				if verified == "" {
					verified = oldVerified
				}
				closesWhen := getString(op.Fields, "closes_when")
				if closesWhen == "" {
					closesWhen = oldClosesWhen
				}

				newEntry := Entry{
					ID:           newEntryID,
					Type:         newType,
					DossierScope: targetScope,
					Text:         getString(op.Fields, "text"),
					Anchors:      anchors,
					Evidence:     evidence,
					Verified:     verified,
					ClosesWhen:   closesWhen,
					Source:       op.Source,
					CreatedAt:    ts,
					UpdatedAt:    ts,
				}

				targetD.Entries = append(targetD.Entries, newEntry)

			case ops.OpRetire:
				reason := getString(op.Fields, "reason")
				d, idx, oldEntry := findActiveEntry(op.DossierScope, op.EntryID)
				if oldEntry != nil {
					retiredEntry := *oldEntry
					retiredEntry.Retired = true
					retiredEntry.RetiredReason = reason
					retiredEntry.UpdatedAt = ts

					d.Entries = append(d.Entries[:idx], d.Entries[idx+1:]...)
					d.History = append(d.History, retiredEntry)
				}

			case ops.OpMove:
				toDossier := getString(op.Fields, "to_dossier")
				targetD := getOrCreateDossier(toDossier)
				d, idx, entry := findActiveEntry(op.DossierScope, op.EntryID)
				if entry != nil {
					movedEntry := *entry
					movedEntry.DossierScope = toDossier
					movedEntry.UpdatedAt = ts

					d.Entries = append(d.Entries[:idx], d.Entries[idx+1:]...)
					targetD.Entries = append(targetD.Entries, movedEntry)
				}

			case ops.OpSplit:
				newDossiers := getStringSlice(op.Fields, "new_dossiers")
				for _, nd := range newDossiers {
					getOrCreateDossier(nd)
				}

				moves := getMapStringString(op.Fields, "entry_moves")
				for entryID, targetScope := range moves {
					targetD := getOrCreateDossier(targetScope)
					d, idx, entry := findActiveEntry(op.DossierScope, entryID)
					if entry != nil {
						movedEntry := *entry
						movedEntry.DossierScope = targetScope
						movedEntry.UpdatedAt = ts

						d.Entries = append(d.Entries[:idx], d.Entries[idx+1:]...)
						targetD.Entries = append(targetD.Entries, movedEntry)
					}
				}
			}
		}
	}

	for _, d := range dossiers {
		sortDossier(d)
	}

	return dossiers, nil
}

func typeRank(t EntryType) int {
	switch t {
	case TypeInvariant:
		return 1
	case TypeRuledOut:
		return 2
	case TypeFailureSignature:
		return 3
	case TypeGotcha:
		return 4
	case TypeDecision:
		return 5
	case TypeProcedure:
		return 6
	case TypeInterface:
		return 7
	case TypeOpenIssue:
		return 8
	default:
		return 99
	}
}

func sortDossier(d *Dossier) {
	sort.Slice(d.Entries, func(i, j int) bool {
		ri := typeRank(d.Entries[i].Type)
		rj := typeRank(d.Entries[j].Type)
		if ri != rj {
			return ri < rj
		}
		return d.Entries[i].ID < d.Entries[j].ID
	})

	sort.Slice(d.History, func(i, j int) bool {
		if !d.History[i].UpdatedAt.Equal(d.History[j].UpdatedAt) {
			return d.History[i].UpdatedAt.Before(d.History[j].UpdatedAt)
		}
		return d.History[i].ID < d.History[j].ID
	})
}

func getString(m map[string]any, key string) string {
	if m == nil {
		return ""
	}
	if v, ok := m[key]; ok {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return ""
}

func getStringSlice(m map[string]any, key string) []string {
	if m == nil {
		return nil
	}
	v, ok := m[key]
	if !ok {
		return nil
	}
	switch val := v.(type) {
	case []string:
		res := make([]string, len(val))
		copy(res, val)
		return res
	case []any:
		var res []string
		for _, item := range val {
			if s, ok := item.(string); ok && s != "" {
				res = append(res, s)
			}
		}
		return res
	}
	return nil
}

func getMapStringString(m map[string]any, key string) map[string]string {
	if m == nil {
		return nil
	}
	v, ok := m[key]
	if !ok {
		return nil
	}
	switch val := v.(type) {
	case map[string]string:
		res := make(map[string]string, len(val))
		for k, v := range val {
			res[k] = v
		}
		return res
	case map[string]any:
		res := make(map[string]string, len(val))
		for k, item := range val {
			if s, ok := item.(string); ok {
				res[k] = s
			}
		}
		return res
	}
	return nil
}

package dossiers

import (
	"fmt"
	"sort"
	"strings"
)

type sectionDef struct {
	title string
	types []EntryType
}

var sections = []sectionDef{
	{
		title: "Invariants",
		types: []EntryType{TypeInvariant},
	},
	{
		title: "Ruled out, failure signatures and gotchas",
		types: []EntryType{TypeRuledOut, TypeFailureSignature, TypeGotcha},
	},
	{
		title: "Decisions",
		types: []EntryType{TypeDecision},
	},
	{
		title: "Procedures",
		types: []EntryType{TypeProcedure},
	},
	{
		title: "Interfaces and dependencies",
		types: []EntryType{TypeInterface},
	},
	{
		title: "Open issues",
		types: []EntryType{TypeOpenIssue},
	},
}

// RenderDossier renders a Dossier to a deterministic Markdown document.
func RenderDossier(d *Dossier) string {
	if d == nil {
		return ""
	}

	var blocks []string
	blocks = append(blocks, fmt.Sprintf("# %s", d.Scope))

	if strings.TrimSpace(d.Purpose) != "" {
		blocks = append(blocks, fmt.Sprintf("## Purpose and boundaries\n%s", strings.TrimSpace(d.Purpose)))
	}

	for _, sec := range sections {
		var secEntries []Entry
		for _, e := range d.Entries {
			for _, t := range sec.types {
				if e.Type == t {
					secEntries = append(secEntries, e)
					break
				}
			}
		}

		if len(secEntries) == 0 {
			continue
		}

		var entryStrs []string
		for _, e := range secEntries {
			entryStrs = append(entryStrs, renderEntry(e))
		}
		secBlock := fmt.Sprintf("## %s\n\n%s", sec.title, strings.Join(entryStrs, "\n\n"))
		blocks = append(blocks, secBlock)
	}

	return strings.Join(blocks, "\n\n") + "\n"
}

func renderEntry(e Entry) string {
	lines := strings.Split(strings.TrimSpace(e.Text), "\n")
	title := ""
	if len(lines) > 0 {
		title = strings.TrimSpace(lines[0])
		if strings.HasPrefix(title, "###") {
			title = strings.TrimSpace(strings.TrimPrefix(title, "###"))
		}
		if strings.HasPrefix(title, "["+e.ID+"]") {
			title = strings.TrimSpace(strings.TrimPrefix(title, "["+e.ID+"]"))
		}
	}

	var metaParts []string
	metaParts = append(metaParts, string(e.Type))
	if len(e.Anchors) > 0 {
		metaParts = append(metaParts, "anchors: "+strings.Join(e.Anchors, ", "))
	}
	if e.Verified != "" {
		metaParts = append(metaParts, "verified "+e.Verified)
	}
	if len(e.Evidence) > 0 {
		metaParts = append(metaParts, "evidence: "+strings.Join(e.Evidence, ", "))
	}
	if e.ClosesWhen != "" {
		metaParts = append(metaParts, "closes-when: "+e.ClosesWhen)
	}

	header := fmt.Sprintf("### [%s] %s", e.ID, title)
	meta := "`" + strings.Join(metaParts, " · ") + "`"

	if len(lines) > 1 {
		body := strings.TrimSpace(strings.Join(lines[1:], "\n"))
		if body != "" {
			return header + "\n" + meta + "\n" + body
		}
	}
	return header + "\n" + meta
}

// RenderHistory renders the .history.md file containing retired and superseded entries.
func RenderHistory(d *Dossier) string {
	if d == nil || len(d.History) == 0 {
		return ""
	}

	var blocks []string
	blocks = append(blocks, fmt.Sprintf("# %s (history)", d.Scope))

	var entryStrs []string
	for _, e := range d.History {
		entryStrs = append(entryStrs, renderHistoryEntry(e))
	}
	blocks = append(blocks, strings.Join(entryStrs, "\n\n"))

	return strings.Join(blocks, "\n\n") + "\n"
}

func renderHistoryEntry(e Entry) string {
	lines := strings.Split(strings.TrimSpace(e.Text), "\n")
	title := ""
	if len(lines) > 0 {
		title = strings.TrimSpace(lines[0])
		if strings.HasPrefix(title, "###") {
			title = strings.TrimSpace(strings.TrimPrefix(title, "###"))
		}
		if strings.HasPrefix(title, "["+e.ID+"]") {
			title = strings.TrimSpace(strings.TrimPrefix(title, "["+e.ID+"]"))
		}
	}

	var metaParts []string
	metaParts = append(metaParts, string(e.Type))
	if len(e.Anchors) > 0 {
		metaParts = append(metaParts, "anchors: "+strings.Join(e.Anchors, ", "))
	}
	if e.Verified != "" {
		metaParts = append(metaParts, "verified "+e.Verified)
	}
	if len(e.Evidence) > 0 {
		metaParts = append(metaParts, "evidence: "+strings.Join(e.Evidence, ", "))
	}
	if e.RetiredReason != "" {
		metaParts = append(metaParts, "retired: "+e.RetiredReason)
	}
	if e.SupersededBy != "" {
		metaParts = append(metaParts, "superseded-by: "+e.SupersededBy)
	}

	header := fmt.Sprintf("### [%s] %s", e.ID, title)
	meta := "`" + strings.Join(metaParts, " · ") + "`"

	if len(lines) > 1 {
		body := strings.TrimSpace(strings.Join(lines[1:], "\n"))
		if body != "" {
			return header + "\n" + meta + "\n" + body
		}
	}
	return header + "\n" + meta
}

// RenderAtlas renders the ATLAS.md markdown table for all dossiers.
func RenderAtlas(atlas *Atlas) string {
	var b strings.Builder
	b.WriteString("# Knowledge Atlas\n\n")
	b.WriteString("| Scope | Kind | Entries | Last Updated |\n")
	b.WriteString("|---|---|---|---|\n")

	if atlas == nil || len(atlas.Dossiers) == 0 {
		return b.String()
	}

	dossiers := make([]AtlasEntry, len(atlas.Dossiers))
	copy(dossiers, atlas.Dossiers)
	sort.Slice(dossiers, func(i, j int) bool {
		return dossiers[i].Scope < dossiers[j].Scope
	})

	for _, d := range dossiers {
		lastUpdated := "-"
		if !d.LastUpdated.IsZero() {
			lastUpdated = d.LastUpdated.UTC().Format("2006-01-02")
		}
		b.WriteString(fmt.Sprintf("| %s | %s | %d | %s |\n", d.Scope, d.Kind, d.EntryCount, lastUpdated))
	}

	return b.String()
}

package dossiers

import (
	"fmt"
	"os"
	"path/filepath"
)

// Writer writes rendered dossiers, history, and atlas to disk.
type Writer struct {
	baseDir string
}

// NewWriter creates a new Writer pointing to the base directory (the .memory/ directory).
func NewWriter(baseDir string) *Writer {
	return &Writer{
		baseDir: baseDir,
	}
}

// WriteDossier writes a rendered dossier and its history (if non-empty) to disk.
func (w *Writer) WriteDossier(d *Dossier) error {
	if d == nil {
		return nil
	}
	dossierPath := filepath.Join(w.baseDir, "dossiers", d.Scope+".md")
	if err := os.MkdirAll(filepath.Dir(dossierPath), 0755); err != nil {
		return fmt.Errorf("create dossier directory: %w", err)
	}

	rendered := RenderDossier(d)
	if err := os.WriteFile(dossierPath, []byte(rendered), 0644); err != nil {
		return fmt.Errorf("write dossier %s: %w", d.Scope, err)
	}

	if len(d.History) > 0 {
		historyPath := filepath.Join(w.baseDir, "dossiers", d.Scope+".history.md")
		renderedHistory := RenderHistory(d)
		if err := os.WriteFile(historyPath, []byte(renderedHistory), 0644); err != nil {
			return fmt.Errorf("write history %s: %w", d.Scope, err)
		}
	}

	return nil
}

// WriteAtlas writes the rendered atlas to .memory/ATLAS.md.
func (w *Writer) WriteAtlas(atlas *Atlas) error {
	atlasPath := filepath.Join(w.baseDir, "ATLAS.md")
	if err := os.MkdirAll(filepath.Dir(atlasPath), 0755); err != nil {
		return fmt.Errorf("create atlas directory: %w", err)
	}

	rendered := RenderAtlas(atlas)
	if err := os.WriteFile(atlasPath, []byte(rendered), 0644); err != nil {
		return fmt.Errorf("write atlas: %w", err)
	}

	return nil
}

// WriteAll writes all dossiers, their histories, and the atlas.
func (w *Writer) WriteAll(dossiers map[string]*Dossier) error {
	for _, d := range dossiers {
		if err := w.WriteDossier(d); err != nil {
			return err
		}
	}

	atlas := BuildAtlas(dossiers)
	if err := w.WriteAtlas(atlas); err != nil {
		return err
	}

	return nil
}

package dossiers

import (
	"fmt"
	"strings"
)

// LintDossier checks a dossier against formatting and size rules, returning warnings.
func LintDossier(d *Dossier) []string {
	if d == nil {
		return nil
	}

	var warnings []string

	rendered := RenderDossier(d)
	if len(rendered) > 12000 {
		estimatedTokens := len(rendered) / 4
		warnings = append(warnings, fmt.Sprintf("dossier %s exceeds ~3k token cap (estimated %d tokens)", d.Scope, estimatedTokens))
	}

	for _, e := range d.Entries {
		lines := strings.Split(strings.TrimSpace(e.Text), "\n")
		if len(lines) > 6 {
			warnings = append(warnings, fmt.Sprintf("entry %s exceeds 6 lines", e.ID))
		}
	}

	if strings.TrimSpace(d.Purpose) == "" {
		warnings = append(warnings, "dossier has no purpose section")
	}

	return warnings
}

package dossiers

import (
	"strings"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/ops"
)

type parsedMarkdownEntry struct {
	id         string
	entryType  EntryType
	title      string
	body       []string
	text       string
	anchors    []string
	verified   string
	evidence   []string
	closesWhen string
}

// DetectHandEdits compares a rendered version of a dossier against on-disk content.
// It returns amend ops for changed entries and add ops for new entries.
func DetectHandEdits(rendered string, onDisk string) ([]ops.Op, error) {
	if strings.TrimSpace(rendered) == strings.TrimSpace(onDisk) {
		return []ops.Op{}, nil
	}

	renderedScope, renderedList := parseMarkdown(rendered)
	onDiskScope, onDiskList := parseMarkdown(onDisk)

	scope := onDiskScope
	if scope == "" {
		scope = renderedScope
	}

	renderedMap := make(map[string]parsedMarkdownEntry)
	for _, e := range renderedList {
		if e.id != "" {
			renderedMap[e.id] = e
		}
	}

	now := time.Now().UTC()
	var detectedOps []ops.Op

	for _, entry := range onDiskList {
		if strings.TrimSpace(entry.text) == "" {
			continue
		}

		if entry.id != "" {
			if rend, exists := renderedMap[entry.id]; exists {
				textChanged := strings.TrimSpace(entry.text) != strings.TrimSpace(rend.text)
				anchorsChanged := !equalStringSlices(entry.anchors, rend.anchors)
				evidenceChanged := !equalStringSlices(entry.evidence, rend.evidence)
				verifiedChanged := entry.verified != rend.verified

				if textChanged || anchorsChanged || evidenceChanged || verifiedChanged {
					fields := map[string]any{
						"text": strings.TrimSpace(entry.text),
					}
					if len(entry.anchors) > 0 || len(rend.anchors) > 0 {
						fields["anchors"] = entry.anchors
					}
					if len(entry.evidence) > 0 || len(rend.evidence) > 0 {
						fields["evidence"] = entry.evidence
					}
					if entry.verified != "" || rend.verified != "" {
						fields["verified"] = entry.verified
					}

					detectedOps = append(detectedOps, ops.Op{
						Type:         ops.OpAmend,
						EntryID:      entry.id,
						DossierScope: scope,
						Timestamp:    now,
						Source:       ops.SourceHuman,
						Fields:       fields,
					})
				}
				continue
			}
		}

		// New entry added on disk
		newID := entry.id
		if newID == "" {
			prefix := PrefixForType(entry.entryType)
			if prefix == "" {
				prefix = "inv-"
			}
			newID = ops.NewEntryID(prefix)
		}

		fields := map[string]any{
			"text": strings.TrimSpace(entry.text),
		}
		if entry.entryType != "" {
			fields["type"] = string(entry.entryType)
		}
		if len(entry.anchors) > 0 {
			fields["anchors"] = entry.anchors
		}
		if len(entry.evidence) > 0 {
			fields["evidence"] = entry.evidence
		}
		if entry.verified != "" {
			fields["verified"] = entry.verified
		}
		if entry.closesWhen != "" {
			fields["closes_when"] = entry.closesWhen
		}

		detectedOps = append(detectedOps, ops.Op{
			Type:         ops.OpAdd,
			EntryID:      newID,
			DossierScope: scope,
			Timestamp:    now,
			Source:       ops.SourceHuman,
			Fields:       fields,
		})
	}

	if detectedOps == nil {
		return []ops.Op{}, nil
	}

	return detectedOps, nil
}

func parseMarkdown(content string) (string, []parsedMarkdownEntry) {
	lines := strings.Split(content, "\n")
	scope := ""
	currentSection := ""
	var cur *parsedMarkdownEntry
	var entries []parsedMarkdownEntry

	finalize := func() {
		if cur == nil {
			return
		}
		bodyText := strings.TrimSpace(strings.Join(cur.body, "\n"))
		if bodyText != "" {
			cur.text = cur.title + "\n" + bodyText
		} else {
			cur.text = cur.title
		}
		entries = append(entries, *cur)
		cur = nil
	}

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)

		if scope == "" && strings.HasPrefix(trimmed, "# ") && !strings.Contains(trimmed, "(history)") {
			scope = strings.TrimSpace(strings.TrimPrefix(trimmed, "# "))
			continue
		}

		if strings.HasPrefix(trimmed, "## ") {
			finalize()
			currentSection = strings.TrimSpace(strings.TrimPrefix(trimmed, "## "))
			continue
		}

		if strings.HasPrefix(trimmed, "### ") {
			finalize()
			headerRest := strings.TrimSpace(strings.TrimPrefix(trimmed, "### "))
			var id, title string
			if strings.HasPrefix(headerRest, "[") {
				closeBracket := strings.Index(headerRest, "]")
				if closeBracket > 0 {
					id = strings.TrimSpace(headerRest[1:closeBracket])
					title = strings.TrimSpace(headerRest[closeBracket+1:])
				} else {
					title = headerRest
				}
			} else {
				title = headerRest
			}

			entryType := TypeFromID(id)
			if entryType == "" {
				lowerSec := strings.ToLower(currentSection)
				switch {
				case strings.Contains(lowerSec, "invariant"):
					entryType = TypeInvariant
				case strings.Contains(lowerSec, "ruled out"):
					entryType = TypeRuledOut
				case strings.Contains(lowerSec, "decision"):
					entryType = TypeDecision
				case strings.Contains(lowerSec, "procedure"):
					entryType = TypeProcedure
				case strings.Contains(lowerSec, "interface"):
					entryType = TypeInterface
				case strings.Contains(lowerSec, "issue"):
					entryType = TypeOpenIssue
				default:
					entryType = TypeInvariant
				}
			}

			cur = &parsedMarkdownEntry{
				id:        id,
				title:     title,
				entryType: entryType,
			}
			continue
		}

		if cur != nil {
			if strings.HasPrefix(trimmed, "`") && strings.HasSuffix(trimmed, "`") && len(cur.body) == 0 && cur.text == "" {
				metaContent := strings.Trim(trimmed, "`")
				parts := strings.Split(metaContent, " · ")
				for i, p := range parts {
					p = strings.TrimSpace(p)
					if i == 0 {
						if t := EntryType(p); t != "" {
							cur.entryType = t
						}
						continue
					}
					if strings.HasPrefix(p, "anchors:") {
						anchorsStr := strings.TrimSpace(strings.TrimPrefix(p, "anchors:"))
						if anchorsStr != "" {
							for _, a := range strings.Split(anchorsStr, ",") {
								if aTrim := strings.TrimSpace(a); aTrim != "" {
									cur.anchors = append(cur.anchors, aTrim)
								}
							}
						}
					} else if strings.HasPrefix(p, "verified ") {
						cur.verified = strings.TrimSpace(strings.TrimPrefix(p, "verified "))
					} else if strings.HasPrefix(p, "evidence:") {
						evStr := strings.TrimSpace(strings.TrimPrefix(p, "evidence:"))
						if evStr != "" {
							for _, ev := range strings.Split(evStr, ",") {
								if evTrim := strings.TrimSpace(ev); evTrim != "" {
									cur.evidence = append(cur.evidence, evTrim)
								}
							}
						}
					} else if strings.HasPrefix(p, "closes-when:") {
						cur.closesWhen = strings.TrimSpace(strings.TrimPrefix(p, "closes-when:"))
					}
				}
				continue
			}

			cur.body = append(cur.body, line)
		}
	}

	finalize()
	return scope, entries
}

func equalStringSlices(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

package dossiers

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
