	"github.com/cblabs-org/repo-memory-plugin/internal/core/ops"
)

func TestRoundTrip(t *testing.T) {
	tempDir := t.TempDir()
	opsWriter := ops.NewWriter(tempDir)

	now := time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
	batch := ops.NewBatch([]ops.Op{
		{
			Type:         ops.OpAdd,
			EntryID:      "inv-01J5K3",
			DossierScope: "core/transcript-parser",
			Timestamp:    now,
			Source:       ops.SourceTurnNote,
			Fields: map[string]any{
				"purpose":  "Parses Antigravity transcript_full.jsonl into structured steps.",
				"text":     "Transcript step ordering must be preserved\nSteps are appended in order; the parser must yield them in index order.",
				"type":     "invariant",
				"anchors":  []string{"internal/harness/antigravity/transcript.go"},
				"verified": "2026-10-02 (PR-02a)",
				"evidence": []string{"note-01M4"},
			},
		},
		{
			Type:         ops.OpAdd,
			EntryID:      "rul-7Q2M",
			DossierScope: "core/transcript-parser",
			Timestamp:    now,
			Source:       ops.SourceTurnNote,
			Fields: map[string]any{
				"text":     "Relative hook command paths in hooks.json\nWhy: Antigravity runs hook commands from the directory containing hooks.json, not the repo root.\nDo: generate absolute paths at install time.",
				"type":     "ruled-out",
				"anchors":  []string{"packaging/antigravity/hooks.json", "cmd/repo-memory/cmd_install.go"},
				"verified": "2026-10-01 (E09)",
				"evidence": []string{"note-01M4", "E09"},
			},
		},
	})

	if err := opsWriter.Write(batch); err != nil {
		t.Fatalf("failed to write batch: %v", err)
	}

	opsReader := ops.NewReader(tempDir)
	projector := NewProjector(opsReader)

	// First projection and render
	dossiers1, err := projector.Project(context.Background())
	if err != nil {
		t.Fatalf("project 1 failed: %v", err)
	}
	d1 := dossiers1["core/transcript-parser"]
	if d1 == nil {
		t.Fatalf("expected core/transcript-parser dossier")
	}
	rendered1 := RenderDossier(d1)

	// Second projection and render
	dossiers2, err := projector.Project(context.Background())
	if err != nil {
		t.Fatalf("project 2 failed: %v", err)
	}
	d2 := dossiers2["core/transcript-parser"]
	rendered2 := RenderDossier(d2)

	// Verify identical output
	if rendered1 != rendered2 {
		t.Fatalf("renderer is not deterministic:\n--- First ---\n%s\n--- Second ---\n%s", rendered1, rendered2)
	}

	// Verify writing to storage and reading back
	storageDir := filepath.Join(tempDir, ".memory")
	writer := NewWriter(storageDir)
	if err := writer.WriteAll(dossiers1); err != nil {
		t.Fatalf("write all failed: %v", err)
	}

	onDiskPath := filepath.Join(storageDir, "dossiers", "core", "transcript-parser.md")
	onDiskBytes, err := os.ReadFile(onDiskPath)
	if err != nil {
		t.Fatalf("failed to read on-disk dossier: %v", err)
	}
	if string(onDiskBytes) != rendered1 {
		t.Fatalf("on-disk content does not match rendered output")
	}

	// Hand-edit check with identical content should return empty
	diffOps, err := DetectHandEdits(rendered1, string(onDiskBytes))
	if err != nil {
		t.Fatalf("detect hand edits error: %v", err)
	}
	if len(diffOps) != 0 {
		t.Fatalf("expected 0 ops for identical content, got %d", len(diffOps))
	}
}

func TestProjector_Lifecycle(t *testing.T) {
	tempDir := t.TempDir()
	opsWriter := ops.NewWriter(tempDir)
	now := time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)

	batch := ops.NewBatch([]ops.Op{
		{
			Type:         ops.OpAdd,
			EntryID:      "inv-01",
			DossierScope: "core/parser",
			Timestamp:    now,
			Source:       ops.SourceTurnNote,
			Fields: map[string]any{
				"text": "Initial parser invariant",
			},
		},
		{
			Type:         ops.OpAdd,
			EntryID:      "got-01",
			DossierScope: "core/parser",
			Timestamp:    now,
			Source:       ops.SourceTurnNote,
			Fields: map[string]any{
				"text": "Initial parser gotcha",
			},
		},
		{
			Type:         ops.OpAdd,
			EntryID:      "proc-01",
			DossierScope: "core/parser",
			Timestamp:    now,
			Source:       ops.SourceTurnNote,
			Fields: map[string]any{
				"text": "Initial procedure",
			},
		},
		{
			Type:         ops.OpAmend,
			EntryID:      "inv-01",
			DossierScope: "core/parser",
			Timestamp:    now.Add(time.Hour),
			Fields: map[string]any{
				"text":    "Amended parser invariant\nMust hold at all times.",
				"anchors": []string{"parser.go"},
			},
		},
		{
			Type:         ops.OpSupersede,
			EntryID:      "got-01",
			DossierScope: "core/parser",
			Timestamp:    now.Add(2 * time.Hour),
			Fields: map[string]any{
				"new_entry_id": "got-02",
				"text":         "Replacement gotcha",
				"reason":       "improved in v2",
			},
		},
		{
			Type:         ops.OpRetire,
			EntryID:      "proc-01",
			DossierScope: "core/parser",
			Timestamp:    now.Add(3 * time.Hour),
			Fields: map[string]any{
				"reason": "procedure deprecated",
			},
		},
		{
			Type:         ops.OpMove,
			EntryID:      "inv-01",
			DossierScope: "core/parser",
			Timestamp:    now.Add(4 * time.Hour),
			Fields: map[string]any{
				"to_dossier": "core/storage",
			},
		},
	})

	if err := opsWriter.Write(batch); err != nil {
		t.Fatalf("failed to write batch: %v", err)
	}

	reader := ops.NewReader(tempDir)
	projector := NewProjector(reader)
	dossiers, err := projector.Project(context.Background())
	if err != nil {
		t.Fatalf("project failed: %v", err)
	}

	parserD := dossiers["core/parser"]
	if parserD == nil {
		t.Fatalf("expected core/parser dossier")
	}

	// Active entries in core/parser should only be got-02
	if len(parserD.Entries) != 1 {
		t.Fatalf("expected 1 active entry in core/parser, got %d", len(parserD.Entries))
	}
	if parserD.Entries[0].ID != "got-02" {
		t.Errorf("expected active entry got-02, got %s", parserD.Entries[0].ID)
	}

	// History in core/parser should have got-01 and proc-01
	if len(parserD.History) != 2 {
		t.Fatalf("expected 2 history entries in core/parser, got %d", len(parserD.History))
	}
	histMap := make(map[string]Entry)
	for _, h := range parserD.History {
		histMap[h.ID] = h
	}
	if got1, ok := histMap["got-01"]; !ok {
		t.Errorf("missing got-01 in history")
	} else {
		if !got1.Retired || got1.SupersededBy != "got-02" || got1.RetiredReason != "improved in v2" {
			t.Errorf("unexpected got-01 history state: %+v", got1)
		}
	}
	if proc1, ok := histMap["proc-01"]; !ok {
		t.Errorf("missing proc-01 in history")
	} else {
		if !proc1.Retired || proc1.RetiredReason != "procedure deprecated" {
			t.Errorf("unexpected proc-01 history state: %+v", proc1)
		}
	}

	// core/storage should contain moved inv-01
	storageD := dossiers["core/storage"]
	if storageD == nil {
		t.Fatalf("expected core/storage dossier")
	}
	if len(storageD.Entries) != 1 {
		t.Fatalf("expected 1 entry in core/storage, got %d", len(storageD.Entries))
	}
	movedEntry := storageD.Entries[0]
	if movedEntry.ID != "inv-01" {
		t.Errorf("expected inv-01 in core/storage, got %s", movedEntry.ID)
	}
	if !strings.Contains(movedEntry.Text, "Amended parser invariant") {
		t.Errorf("expected amended text, got %q", movedEntry.Text)
	}
	if len(movedEntry.Anchors) != 1 || movedEntry.Anchors[0] != "parser.go" {
		t.Errorf("expected parser.go anchor, got %v", movedEntry.Anchors)
	}
}

func TestProjector_Split(t *testing.T) {
