func TestRenderer_AllEntryTypes(t *testing.T) {
	d := &Dossier{
		Scope:   "core/full-catalog",
		Kind:    KindModule,
		Purpose: "Catalog of all supported dossier entry types.",
		Entries: []Entry{
			{
				ID:       "inv-01",
				Type:     TypeInvariant,
				Text:     "State must be deterministic\nAll hashes match across executions.",
				Anchors:  []string{"core/state.go"},
				Verified: "2026-10-02 (PR-01)",
				Evidence: []string{"note-1"},
			},
			{
				ID:       "rul-01",
				Type:     TypeRuledOut,
				Text:     "No global mutable singletons\nWhy: Causes race conditions.",
				Anchors:  []string{"core/globals.go"},
				Evidence: []string{"note-2"},
			},
			{
				ID:       "fail-01",
				Type:     TypeFailureSignature,
				Text:     "Connection timeout signature\nMatches when socket hangs during sync.",
				Anchors:  []string{"net/client.go"},
			},
			{
				ID:       "got-01",
				Type:     TypeGotcha,
				Text:     "Working directory caveat\nHooks run in their parent directory.",
			},
			{
				ID:       "dec-01",
				Type:     TypeDecision,
				Text:     "Event sourcing storage model\nWe use an append-only op log.",
			},
			{
				ID:       "proc-01",
				Type:     TypeProcedure,
				Text:     "Release cut procedure\nStep 1: run test suite.\nStep 2: tag commit.",
			},
			{
				ID:       "iface-01",
				Type:     TypeInterface,
				Text:     "Op log reader interface\nIterate method returns iter.Seq2.",
			},
			{
				ID:         "issue-01",
				Type:       TypeOpenIssue,
				Text:       "High latency in cold start\nInvestigate lazy initialization.",
				ClosesWhen: "benchmarks pass under 50ms",
			},
		},
	}

	rendered := RenderDossier(d)

	// Check sections order and existence
	invIdx := strings.Index(rendered, "## Invariants")
	rulIdx := strings.Index(rendered, "## Ruled out, failure signatures and gotchas")
	decIdx := strings.Index(rendered, "## Decisions")
	procIdx := strings.Index(rendered, "## Procedures")
	ifaceIdx := strings.Index(rendered, "## Interfaces and dependencies")
	issueIdx := strings.Index(rendered, "## Open issues")

	if invIdx == -1 || rulIdx == -1 || decIdx == -1 || procIdx == -1 || ifaceIdx == -1 || issueIdx == -1 {
		t.Fatalf("one or more expected sections missing in rendered output:\n%s", rendered)
	}

	if !(invIdx < rulIdx && rulIdx < decIdx && decIdx < procIdx && procIdx < ifaceIdx && ifaceIdx < issueIdx) {
		t.Fatalf("sections are not in expected order:\n%s", rendered)
	}

	// Check individual entry formatting
	if !strings.Contains(rendered, "### [inv-01] State must be deterministic") {
		t.Errorf("missing invariant entry header")
	}
	if !strings.Contains(rendered, "`invariant · anchors: core/state.go · verified 2026-10-02 (PR-01) · evidence: note-1`") {
		t.Errorf("missing invariant metadata line")
	}
	if !strings.Contains(rendered, "All hashes match across executions.") {
		t.Errorf("missing invariant remaining body line")
	}

	if !strings.Contains(rendered, "### [issue-01] High latency in cold start") {
		t.Errorf("missing issue entry header")
	}
	if !strings.Contains(rendered, "`open-issue · closes-when: benchmarks pass under 50ms`") {
		t.Errorf("missing issue metadata line with closes-when")
	}
}

