func TestLintDossier(t *testing.T) {
	// Clean dossier
	cleanD := &Dossier{
		Scope:   "core/clean",
		Kind:    KindModule,
		Purpose: "Clean purpose description.",
		Entries: []Entry{
			{
				ID:   "inv-01",
				Type: TypeInvariant,
				Text: "Line 1\nLine 2\nLine 3",
			},
		},
	}
	cleanWarnings := LintDossier(cleanD)
	if len(cleanWarnings) != 0 {
		t.Errorf("expected 0 warnings for clean dossier, got %v", cleanWarnings)
	}

	// Missing purpose warning
	noPurposeD := &Dossier{
		Scope: "core/no-purpose",
		Entries: []Entry{
			{
				ID:   "inv-01",
				Type: TypeInvariant,
				Text: "Valid text",
			},
		},
	}
	w1 := LintDossier(noPurposeD)
	foundPurposeWarning := false
	for _, w := range w1 {
		if strings.Contains(w, "dossier has no purpose section") {
			foundPurposeWarning = true
		}
	}
	if !foundPurposeWarning {
		t.Errorf("expected purpose warning, got %v", w1)
	}

	// Entry exceeding 6 lines warning
	longEntryD := &Dossier{
		Scope:   "core/long-entry",
		Purpose: "Purpose present",
		Entries: []Entry{
			{
				ID:   "inv-long",
				Type: TypeInvariant,
				Text: "Line 1\nLine 2\nLine 3\nLine 4\nLine 5\nLine 6\nLine 7",
			},
		},
	}
	w2 := LintDossier(longEntryD)
	foundLineWarning := false
	for _, w := range w2 {
		if strings.Contains(w, "entry inv-long exceeds 6 lines") {
			foundLineWarning = true
		}
	}
	if !foundLineWarning {
		t.Errorf("expected line count warning, got %v", w2)
	}

	// Oversized dossier warning (>12k bytes)
	largeText := strings.Repeat("Lorem ipsum dolor sit amet, consectetur adipiscing elit. ", 250) // ~14k bytes
	oversizedD := &Dossier{
		Scope:   "core/oversized",
		Purpose: "Large purpose text",
		Entries: []Entry{
			{
				ID:   "inv-big",
				Type: TypeInvariant,
				Text: "Title\n" + largeText,
			},
		},
	}
	w3 := LintDossier(oversizedD)
	foundSizeWarning := false
	for _, w := range w3 {
		if strings.Contains(w, "exceeds ~3k token cap (estimated") {
			foundSizeWarning = true
		}
	}
	if !foundSizeWarning {
		t.Errorf("expected oversized cap warning, got %v", w3)
	}
}

func TestHandEdit_Detection(t *testing.T) {
	rendered := `# core/test

## Purpose and boundaries
Test purpose.

## Invariants

### [inv-01] First invariant
` + "`invariant · anchors: foo.go`" + `
Initial body text.

### [inv-02] Second invariant
` + "`invariant`" + `
Untouched body.
`

	// 1. Identical content -> 0 ops
	opsIdentical, err := DetectHandEdits(rendered, rendered)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(opsIdentical) != 0 {
		t.Fatalf("expected 0 ops, got %d", len(opsIdentical))
	}

	// 2. Amend inv-01
	onDiskAmended := strings.Replace(rendered, "Initial body text.", "Edited body text by human.", 1)
	opsAmended, err := DetectHandEdits(rendered, onDiskAmended)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(opsAmended) != 1 {
		t.Fatalf("expected 1 amend op, got %d", len(opsAmended))
	}
	if opsAmended[0].Type != ops.OpAmend || opsAmended[0].EntryID != "inv-01" {
		t.Errorf("expected amend op for inv-01, got %+v", opsAmended[0])
	}
	if err := ops.ValidateOp(opsAmended[0]); err != nil {
		t.Errorf("amend op failed validation: %v", err)
	}

	// 3. Add new entry on disk
	onDiskWithNew := rendered + `
### [rul-01] Added ruled out entry
` + "`ruled-out`" + `
Do not use raw pointers.
`
	opsAdded, err := DetectHandEdits(rendered, onDiskWithNew)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(opsAdded) != 1 {
		t.Fatalf("expected 1 add op, got %d", len(opsAdded))
	}
	if opsAdded[0].Type != ops.OpAdd || opsAdded[0].EntryID != "rul-01" {
		t.Errorf("expected add op for rul-01, got %+v", opsAdded[0])
	}
	if err := ops.ValidateOp(opsAdded[0]); err != nil {
		t.Errorf("add op failed validation: %v", err)
	}

	// 4. Add new entry without ID
	onDiskWithoutID := rendered + `
### New invariant without ID
` + "`invariant`" + `
Auto-assign ID.
`
	opsNoID, err := DetectHandEdits(rendered, onDiskWithoutID)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(opsNoID) != 1 {
		t.Fatalf("expected 1 add op, got %d", len(opsNoID))
	}
	if opsNoID[0].Type != ops.OpAdd || !strings.HasPrefix(opsNoID[0].EntryID, "inv-") {
		t.Errorf("expected generated inv- ID, got %s", opsNoID[0].EntryID)
	}
	if err := ops.ValidateOp(opsNoID[0]); err != nil {
		t.Errorf("add op failed validation: %v", err)
	}
}

